<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import { api,auth,errorText,hasRole,refreshIdentity } from '../api'
import { useLoad,useRequestKey,roleNames } from '../composables'
import type { User,Page } from '../types'
import PageState from '../components/PageState.vue'
import PaginationBar from '../components/PaginationBar.vue'
import AppIcon from '../components/AppIcon.vue'
const page=ref(0),{data,loading,error,load}=useLoad(()=>api<Page<User>>(`/admin/users?page=${page.value}&size=20`)),router=useRouter()
const adding=ref(false),busy=ref(false),saveError=ref(''),success=ref(''),key=useRequestKey()
const form=reactive({username:'',displayName:'',password:'',roles:['OBSERVER'] as string[]})
const editing=ref<{user:User;roles:string[];reason:string;action:'roles'|'active'}|null>(null)
const roles=['OBSERVER','ON_CALL','OPS_ADMIN','AUDITOR']
onMounted(load)
function create(){adding.value=true;editing.value=null;saveError.value='';success.value=''}
function cancel(){adding.value=false;editing.value=null;form.password='';key.clear();saveError.value=''}
function edit(user:User,action:'roles'|'active'){adding.value=false;form.password='';key.clear();editing.value={user,roles:[...user.roles],reason:'',action};saveError.value='';success.value=''}
async function saveNew(){busy.value=true;saveError.value='';try{if(new TextEncoder().encode(form.password).length>72)throw new Error('密码不能超过 72 个 UTF-8 字节。');const body={username:form.username,displayName:form.displayName,password:form.password,roles:form.roles};await api('/admin/users',{method:'POST',body,key:key.forBody(body)});form.password='';key.clear();adding.value=false;success.value='用户已创建。还需要在对应目标的“访问权限”中分配资源权限。';await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
async function saveExisting(){const e=editing.value;if(!e)return;busy.value=true;saveError.value='';try{await api(`/admin/users/${e.user.id}/${e.action==='roles'?'roles':'active'}`,{method:'PUT',body:e.action==='roles'?{roles:e.roles,reason:e.reason}:{active:!e.user.active,reason:e.reason}});editing.value=null;success.value='用户配置已更新。';if(e.user.id===auth.user?.id){await refreshIdentity();if(!hasRole('OPS_ADMIN'))await router.replace('/overview')}await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
async function copyId(id:string){try{await navigator.clipboard.writeText(id);success.value='用户 ID 已复制。'}catch{success.value='请手动复制用户 ID：'+id}}
</script>
<template><div class="page-heading"><div><h1>用户与角色</h1><p>按职责分配角色，并在目标详情中设置读取与操作权限。</p></div><button class="btn primary" @click="create"><AppIcon name="plus" :size="17" />创建用户</button></div><div v-if="success" class="success-message" role="status">{{ success }}</div><section class="panel"><form v-if="adding" class="inline-form" @submit.prevent="saveNew"><h2>创建用户</h2><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><div class="form-grid"><label>用户名<input v-model="form.username" required pattern="[A-Za-z0-9_.-]{3,80}" minlength="3" maxlength="80" autocomplete="off"></label><label>显示名称<input v-model="form.displayName" required maxlength="120"></label><label class="span-2">初始密码<input v-model="form.password" required type="password" minlength="12" maxlength="72" autocomplete="new-password"><small>至少 12 个字符，至多 72 个 UTF-8 字节；密码不会在列表中回显。</small></label><fieldset class="role-options span-2"><legend>用户角色</legend><label v-for="r in roles" :key="r" class="check-label"><input v-model="form.roles" type="checkbox" :value="r">{{ roleNames[r] }}</label></fieldset></div><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="cancel">取消</button><button class="btn primary" :disabled="busy||!form.roles.length">{{ busy?'创建中…':'创建用户' }}</button></div></form><form v-if="editing" class="inline-form" @submit.prevent="saveExisting"><h2>{{ editing.action==='roles'?'编辑角色':editing.user.active?'停用用户':'启用用户' }} · {{ editing.user.displayName }}</h2><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><fieldset v-if="editing.action==='roles'" class="role-options"><legend>授予的角色</legend><label v-for="r in roles" :key="r" class="check-label"><input v-model="editing.roles" type="checkbox" :value="r">{{ roleNames[r] }}</label></fieldset><p v-else class="muted">{{ editing.user.active?'停用后，该用户全部登录会话将立即失效。':'启用后，用户可使用现有密码重新登录。' }}</p><label>变更理由<input v-model="editing.reason" required maxlength="500"></label><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="cancel">取消</button><button class="btn primary" :disabled="busy">{{ busy?'保存中…':'确认变更' }}</button></div></form><PageState :loading="loading&&!data" :error="error" :empty="!!data&&!data.items.length" title="没有用户记录" @retry="load"><template v-if="data"><div class="table-scroll"><table><thead><tr><th>用户</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in data.items" :key="u.id"><td><strong>{{ u.displayName }}</strong><small class="cell-note">{{ u.username }}</small><button class="text-button small" @click="copyId(u.id)">复制 ID</button></td><td><div class="role-tags"><span v-for="r in u.roles" :key="r" class="env-tag">{{ roleNames[r]||r }}</span><span v-if="!u.roles.length" class="muted">未分配</span></div></td><td><span class="status" :class="u.active?'good':'neutral'"><span class="status-dot"></span>{{ u.active?'活跃':'已停用' }}</span></td><td><div class="row-actions"><button class="text-button" @click="edit(u,'roles')">编辑角色</button><button class="text-button" :class="{danger:u.active}" @click="edit(u,'active')">{{ u.active?'停用':'启用' }}</button></div></td></tr></tbody></table></div><PaginationBar :page="page" :size="20" :total="data.total" :loading="loading" @change="p=>{page=p;load()}" /></template></PageState></section><p class="form-hint">管理员角色不自动包含值班职责。处理事故需同时授予 ON_CALL 与对应目标的操作权限。</p></template>
